            modelBound = false,
            cmeActualActivated = false,
            sanctuaryActualActivated = false
        };
        var primeWeatherRegister = new
        {
            schema = "project-sanctuary.prime.extended-telemetry-weather.v1",
            createdAtUtc = timestamp,
            cmeId = request.CmeId,
            manager = "Prime",
            sourceOwner = "Cryptic",
