        AppendJsonLine(
            selfGelLedgerPath,
            JsonSerializer.Serialize(new
            {
                schema = "project-sanctuary.selfgel-lab-observation-reconstruction-support.v1",
                eventType = "selfgel-lab-observation-reconstruction-support",
                timestampUtc = timestamp,
